const data = {{workflowparams:data}};
const docFormat = {{node:get_node_DtdS8ckv.data.data.id}};
let miList = [];

for(const production of data.production_list) {
  for(const material of production.material_list) {
    for(const location of material.location_list) {
      if(location.issue_qty > 0) {
        const miData = {
          production_order_id: production.production_order_id,
          production_bom_id: material.production_bom_id,
          schedule_id: material.production_bom_data.schedule_id,
          issue_status: 'Picking',
          source_storage_id: location.storage_location_id,
          source_storage_name: location.storage_location_name,
          source_bin_id: location.bin_location_id,
          source_bin_name: location.bin_location_name,
          target_storage_id: material.target_storage_location,
          target_storage_name: material.production_bom_data.target_storage_name,
          target_bin_id: material.target_bin_location,
          target_bin_name: material.production_bom_data.target_bin_name,
          plan_qty: location.issue_qty,
          actual_qty: 0,
          issue_seq: 0,
          issued_by: {{system:uid}},
          issued_date: new Date().toISOString().split('T')[0],
          batch_id: location.batch_id,
          plant_id: production.plant_id,
          organization_id: data.organization_id,
          issue_no: 'issued',
          issue_no_type: docFormat,
          material_id: material.material_id
        }

          miList.push(miData);
      };
    }
  }
}

return { miList }

