script.code:
const data = {{workflowparams:data}};
let prodBOMList = [];

for(const production of data.production_list) {
  for(const material of production.material_list) {
    const prodBOMData = {
      production_bom_id: material.production_bom_id,
      issue_qty: material.total_issue_qty
    }

    prodBOMList.push(prodBOMData);
  }
}

return {
  prodBOMList
}

const updateProdBOMList = {{node:code_node_FugRpcKM.data.prodBOMList}};
const prodBOMList = {{node:search_node_X29fVR63.data.data}};

const updatedProdBOMList = updateProdBOMList.map(prodBOM => {
  const foundProdBOM = prodBOMList.find(item => item.id === prodBOM.production_bom_id);

  return {
    ...prodBOM,
    issue_qty: (prodBOM.issue_qty || 0) + (foundProdBOM?.issued_plan_qty || 0)
  };
});

return {
  updatedProdBOMList
};

const userID = {{system:uid}};
const now = new Date();
const date = now.toISOString().split('T')[0]; // YYYY-MM-DD
const time = now.toTimeString().split(' ')[0].replace(/:/g, ''); // HHMMSS

// the random tag: two runs of one user in the same second shared one key (GD-2610-2093 reported 2094's invoice, 10-26)
return {
  redis_name: `MI:${userID}:${date}:${time}:${Math.random().toString(36).slice(2, 10)}`
  // Example: "MI:12345:2024-02-24:143022:k3f9x0ab"
};

const addedList = {{node:add_node_IzrB9i0x.data}};
const currentIndexRaw = {{node:get_cache_node_uQ9nXRnc.data}}
const index = currentIndexRaw ? parseInt(currentIndexRaw) : 0

const item = addedList[index];

return {
  plant_id: item.plant_id,
  organization_id: item.organization_id,
  material_id: item.material_id,
  quantity: item.plan_qty,
  trx_no: item.issue_no,
  location_id: item.source_bin_id,
  batch_id: item.batch_id,
  nextIndex: index + 1,
  doc_date: item.issued_date
};
